package com.minecolonies.api.colony.connections;

import com.minecolonies.api.util.BlockPosUtil;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;

import static com.minecolonies.api.util.constant.NbtTagConstants.*;
import static com.minecolonies.api.util.constant.NbtTagConstants.TAG_STATUS;

/**
 * Small storage class to hold colony connection data.
 */
public class ColonyConnection
{
    public DiplomacyStatus diplomacyStatus;
    public int                                      id;
    public String                                   name;
    public BlockPos                                 pos;

    /**
     * Connected Colony Data with:
     *
     * @param id              the colony id.
     * @param name            the colony name (cached).
     * @param pos             the colony gate position (cached).
     * @param diplomacyStatus the diplomacy status of the two colonies.
     */
    public ColonyConnection(
        int id,
        String name,
        BlockPos pos,
        DiplomacyStatus diplomacyStatus)
    {
        this.id = id;
        this.name = name;
        this.pos = pos;
        this.diplomacyStatus = diplomacyStatus;
    }

    /**
     * Constructor for deserialization/serialization.
     */
    public ColonyConnection()
    {
        // noop
    }

    public CompoundTag serializeNBT()
    {
        final CompoundTag compoundTag = new CompoundTag();
        compoundTag.putInt(TAG_ID, id);
        compoundTag.putString(TAG_NAME, name);
        BlockPosUtil.write(compoundTag, TAG_POS, pos);
        compoundTag.putInt(TAG_STATUS, diplomacyStatus.ordinal());
        return compoundTag;
    }

    public ColonyConnection deserializeNBT(final CompoundTag compoundTag)
    {
        this.id = compoundTag.getInt(TAG_ID);
        this.name = compoundTag.getString(TAG_NAME);
        this.pos = BlockPosUtil.read(compoundTag, TAG_POS);
        this.diplomacyStatus = DiplomacyStatus.values()[compoundTag.getInt(TAG_STATUS)];
        return this;
    }

    public void serializeByteBuf(final FriendlyByteBuf buf)
    {
        buf.writeInt(id);
        buf.writeUtf(name);
        buf.writeBlockPos(pos);
        buf.writeInt(diplomacyStatus.ordinal());
    }

    public ColonyConnection deserializeByteBuf(final FriendlyByteBuf buf)
    {
        this.id = buf.readInt();
        this.name = buf.readUtf();
        this.pos = buf.readBlockPos();
        this.diplomacyStatus = DiplomacyStatus.values()[buf.readInt()];
        return this;
    }
}

package com.minecolonies.api.colony.connections;

import com.minecolonies.api.util.BlockPosUtil;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import org.jetbrains.annotations.NotNull;

import static com.minecolonies.api.util.constant.NbtTagConstants.*;

/**
 * Node in the path from one colony to another.
 */
public class ColonyConnectionNode
{
    /**
     * The previous point in the connection grid.
     */
    private BlockPos previousNode = BlockPos.ZERO;

    /**
     * The next point in the connection grid.
     */
    private BlockPos nextNode = BlockPos.ZERO;

    /**
     * Position of this point.
     */
    private final BlockPos position;

    /**
     * Connected colony.
     */
    private int targetColonyId = -1;

    /**
     * Create a new connection node at a given pos.
     * @param position the pos.
     */
    public ColonyConnectionNode(final BlockPos position)
    {
        this.position = position;
    }

    /**
     * Alter the previous node connection.
     * @param previousNode the previous node pos.
     */
    public void alterPreviousNode(final BlockPos previousNode)
    {
        this.previousNode = previousNode;
    }

    /**
     * Alter the next node connection.
     * @param nextNode the next nod epos.
     */
    public void alterNextNode(final BlockPos nextNode)
    {
        this.nextNode = nextNode;
    }

    /**
     * Get position of this point.
     * @return the position.
     */
    public BlockPos getPosition()
    {
        return position;
    }

    /**
     * Get the previous node.
     * @return prev node pos or zero if not set.
     */
    public BlockPos getPreviousNode()
    {
        return previousNode;
    }

    /**
     * Get the next node.
     * @return next node pos or ZERO if not set.
     */
    public BlockPos getNextNode()
    {
        return nextNode;
    }

    /**
     * Get the connected target colony id.
     * @return the target colony id.
     */
    public int getTargetColonyId()
    {
        return targetColonyId;
    }

    /**
     * Set the target colony id.
     * @param targetColonyId the id to set.
     */
    public void setTargetColonyId(final int targetColonyId)
    {
        this.targetColonyId = targetColonyId;
    }

    /**
     * Write connections to NBT data for saving.
     * @return compound NBT-Tag.
     */
    public CompoundTag write()
    {
        final CompoundTag compound = new CompoundTag();
        BlockPosUtil.write(compound, TAG_POS, position);
        BlockPosUtil.write(compound, TAG_PREV_POS, previousNode);
        BlockPosUtil.write(compound, TAG_NEXT_POS, nextNode);
        compound.putInt(TAG_TARGET_COLONY_ID, targetColonyId);
        return compound;
    }

    /**
     * Read connections from saved NBT data.
     *
     * @param compound NBT Tag.
     */
    public void read(@NotNull final CompoundTag compound)
    {
        this.previousNode = BlockPosUtil.read(compound, TAG_PREV_POS);
        this.nextNode = BlockPosUtil.read(compound, TAG_NEXT_POS);
        this.targetColonyId = compound.getInt(TAG_TARGET_COLONY_ID);
    }

    /**
     * If another node can connect to this.
     * @return true if so.
     */
    public boolean hasNextNode()
    {
        return !nextNode.equals(BlockPos.ZERO);
    }
}

package com.minecolonies.api.colony.connections;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;

import static com.minecolonies.api.util.constant.NbtTagConstants.*;
import static com.minecolonies.api.util.constant.NbtTagConstants.TAG_STATUS;

/**
 * Connected Event Data with:
 *
 * @param id              the colony id.
 * @param connectionEventType the event type enum.
 */
public record ConnectionEvent(int id, String name, ConnectionEventType connectionEventType)
{
    public CompoundTag serializeNBT()
    {
        final CompoundTag compoundTag = new CompoundTag();
        compoundTag.putInt(TAG_ID, id);
        compoundTag.putString(TAG_NAME, name);
        compoundTag.putInt(TAG_STATUS, connectionEventType.ordinal());
        return compoundTag;
    }

    public void serializeByteBuf(final FriendlyByteBuf buf)
    {
        buf.writeInt(id);
        buf.writeUtf(name);
        buf.writeInt(connectionEventType.ordinal());
    }

    public static ConnectionEvent deserializeNBT(final CompoundTag compoundTag)
    {
        return new ConnectionEvent(compoundTag.getInt(TAG_ID),
            compoundTag.getString(TAG_NAME),
            ConnectionEventType.values()[compoundTag.getInt(TAG_STATUS)]);
    }

    public static ConnectionEvent deserializeByteBuf(final FriendlyByteBuf buf)
    {
        return new ConnectionEvent(buf.readInt(), buf.readUtf(32767), ConnectionEventType.values()[buf.readInt()]);
    }
}

package com.minecolonies.api.colony.connections;

import com.minecolonies.core.entity.pathfinding.pathjobs.PathJobMoveToLocation;
import com.minecolonies.core.entity.pathfinding.pathresults.PathResult;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import static com.minecolonies.api.util.constant.NbtTagConstants.*;

/**
 * Pending connected colony data while pathfinding is still trying to connect.
 */
public class PendingConnectionNode extends ColonyConnectionNode
{
    /**
     * The different connection types.
     */
    public enum PendingConnectionType
    {
        DEFAULT,
        FIX_PATH,
        CONNECT_COLONY
    }

    /**
     * The connection type.
     */
    private PendingConnectionType connectionType;

    /**
     * Cached path result.
     */
    private PathResult<PathJobMoveToLocation> cachedPathResult;

    /**
     * Create a new pending node.
     * @param pos it's pos.
     * @param pathResult the path result.
     * @param connectionType the connection type.
     */
    public PendingConnectionNode(
        final BlockPos pos,
        final PathResult<PathJobMoveToLocation> pathResult,
        final PendingConnectionType connectionType)
    {
        super(pos);
        this.cachedPathResult = pathResult;
        this.connectionType = connectionType;
    }

    /**
     * Constructor for deserialization/serialization.
     */
    public PendingConnectionNode(final BlockPos pos)
    {
        super(pos);
    }

    /**
     * Write connections to NBT data for saving.
     * @return compound NBT-Tag.
     */
    public CompoundTag write()
    {
        final CompoundTag compound = super.write();
        compound.putInt(TAG_CONNECTION_TYPE, connectionType.ordinal());
        return compound;
    }

    /**
     * Read connections from saved NBT data.
     *
     * @param compound NBT Tag.
     */
    public void read(@NotNull final CompoundTag compound)
    {
        super.read(compound);
        this.connectionType = PendingConnectionType.values()[compound.getInt(TAG_CONNECTION_TYPE)];
    }

    /**
     * If this is a regular connection, or a mending connection (pending connection does not destroy sign if fail to path) or a colony connection.
     * @return the enum type.
     */
    public PendingConnectionType getPendingConnectionType()
    {
        return connectionType;
    }

    /**
     * Store the cached path result.
     * @param cachedPathResult the cached path result.
     */
    public void setCachedPathResult(final PathResult<PathJobMoveToLocation> cachedPathResult)
    {
        this.cachedPathResult = cachedPathResult;
    }

    /**
     * Get the cached path result.
     *
     * @return the cached path result.
     */
    @Nullable
    public PathResult<PathJobMoveToLocation> getCachedPathResult()
    {
        return cachedPathResult;
    }
}

